let _wfMtxUnit = "cr";            // §C flow-matrix unit (cr = ₹ cr | pct = % of AMC equity AUM)
const _WF_MTX_MAXROWS = 30;       // §C heatmap row cap (AMCs), by conviction — keeps it scannable
