          let sv = 0, unk = false; sch.forEach((sr) => { if (sr.s[j] === null) unk = true; else sv += sr.s[j]; });
          rest.s[j] = unk ? null : hv - sv; rest.mv[j] = (r.mv[j] || 0) - sch.reduce((t, sr) => t + (sr.mv[j] || 0), 0);
