  const seg = AB_DD_UNITS.map(([v, l]) => `<button data-v="${v}"${AB.ddu === v ? ' class="active"' : ""}>${fEsc(l)}</button>`).join("");
  const scope = (isCat && S) ? `<span class="seg ab-ddscope" title="Whose holding the table counts: only the funds in this category, month by month as each fund was filed, or every mutual fund.">`
    + `<button data-s="cat"${catOnly ? ' class="active"' : ""}>Only ${fEsc(catName)} funds</button><button data-s="all"${catOnly ? "" : ' class="active"'}>All funds</button></span>` : "";
  const w0 = host.querySelector(".ab-ddwrap"), sl0 = w0 ? w0.scrollLeft : 0, st0 = w0 ? w0.scrollTop : 0;
  // ★ FROZEN PANE (Kyser 2026-09-15: "we need to freeze pane when we scroll to right"). The panel lives in
