    if (primary && !(ocKey in _ocCache)) {
      let R0 = null;
      try { R0 = await fetchJSON(LAZY.base + "one_cost/" + ocKey + ".json"); } catch (e) { R0 = null; }
      _ocCache[ocKey] = R0 || null;
    }
    ocR = primary ? _ocCache[ocKey] : null;
    let pbDone = false;
    const pbH = _abPbHouse(await _abPbIndex(), keyX);
    if (pbH) {
      const wt = ABP.wt === "equal" ? "equal" : "size";
      const types = _abIncList().filter((t) => AB_PB_TYPES.indexOf(t) >= 0 && pbH.ent.buckets[t]);
      const nSch = types.reduce((a, t) => a + (pbH.ent.buckets[t].n_schemes || 0), 0);
      const roleT = {};
      for (const r of ["gross", "direct", "regular", "direct_paired", "regular_paired"]) {
        const parts = types.filter((t) => ((pbH.ent.buckets[t].roles || {})[wt] || []).indexOf(r) >= 0)
          .map((t) => ({ dir: "pb/" + wt + "/" + r + "/" + t, slug: pbH.slug, bucket: t }));
        roleT[r] = parts.length ? _abpCombine(await load(parts), axis) : null;
      }
      // ★ THE PICKS ARE WHOLE OR ABSENT (2026-09-14). A type whose picks cannot be priced for part of the history (SBI's
      // active book by size, until 2025-04) would leave the blended picks holding only the other types for those years
      // while the Direct line holds all of them -- and the difference would be read as a cost (it read -2.52 pp). So the
      // picks start on the day the LAST switched-on type's picks begin, and there are none when a type with plans has
      // no priceable picks at all.
      if (roleT.gross) {
        const has = (t, r) => ((pbH.ent.buckets[t].roles || {})[wt] || []).indexOf(r) >= 0;
        const withPlans = types.filter((t) => has(t, "direct")), withPicks = types.filter((t) => has(t, "gross"));
        if (withPlans.some((t) => withPicks.indexOf(t) < 0)) roleT.gross = null;
        else {
          let g0 = roleT.gross.f;
          withPicks.forEach((t) => { const rec = ABP._cache["pb/" + wt + "/gross/" + t + "/" + pbH.slug]; if (rec && rec.f > g0) g0 = rec.f; });
          for (let k = roleT.gross.f; k < g0; k++) roleT.gross.nav[k] = null;
          roleT.gross.f = g0;
        }
      }
      ABP_PLAN_ROLES.forEach(([_b, r, label, color]) => {
        // counting every scheme equally, the book line itself becomes these picks, so the picks line is not drawn twice
        if (r === "gross" && wt === "equal" && _abpPicksCover(roleT)) return;
        if (roleT[r]) plans.push({ kind: "plan", key: keyX + " · " + label, label: label, plan: r, color: color, n: nSch, T: roleT[r], extra: false });
      });
      pbInfo = { wt: wt, types: types, T: roleT, n: nSch,
                 off: _abIncList().filter((t) => AB_PB_TYPES.indexOf(t) < 0 || !pbH.ent.buckets[t]) };
      pbDone = true;
    }
    if (!pbDone && !_abPlanIx) await _abPlanIndex();
    for (const pl of (pbDone ? [] : _abPlanFor(keyX))) {
      const T = _abpCombine(await load([{ dir: pl.bucket, slug: pl.slug, bucket: pl.bucket }]), axis);
      if (T) plans.push({ kind: "plan", key: keyX + " · " + pl.label, label: pl.label, plan: pl.role, color: pl.color, n: pl.n, T: T, extra: false });
    }
