  let _ci = 0;
  // a plan line comes right after the book it belongs to in `books`, so it takes that book's shade
  books.forEach((b) => { if (!b.plan) _ci++; b.slot = Math.min(Math.max(_ci - 1, 0), 3); b.color = (ABP_FAMILY[b.plan || "book"] || ABP_FAMILY.book)[b.slot] || "#6e7781"; });
  books.forEach((b) => { if (b.plan && b.plan !== "gross") _abpBlankNoNavDays(b.T); });
  const A = books[0].T;
